// mysqlQueries answers every query in Querier against mysql.
type mysqlQueries struct {
	archiveList                     string
	archiveSignup                   string
	createList                      string
	getList                         string
	getListCreatedAt                string
	getSignup                       string
	getSignupByContactDigest        string
	getSignupCreatedAt              string
	insertSignup                    string
	listLists                       string
	listListsDescending             string
	listOpenLists                   string
	listOpenListsDescending         string
	listSignups                     string
	listSignupsDescending           string
	listSignupsForSubject           string
	listSignupsForSubjectDescending string
	transitionSignup                string
	updateList                      string
	updateSignupNotes               string
	withdrawSignup                  string
	withdrawSignupsForSubject       string
}

// newMySQL returns the mysql querier with prefix substituted into every
// table name the analyzer identified.
func newMySQL(prefix string) *mysqlQueries {
	return &mysqlQueries{
		archiveList:                     strings.ReplaceAll(archiveListMySQL, prefixMarker, prefix),
		archiveSignup:                   strings.ReplaceAll(archiveSignupMySQL, prefixMarker, prefix),
		createList:                      strings.ReplaceAll(createListMySQL, prefixMarker, prefix),
		getList:                         strings.ReplaceAll(getListMySQL, prefixMarker, prefix),
		getListCreatedAt:                strings.ReplaceAll(getListCreatedAtMySQL, prefixMarker, prefix),
		getSignup:                       strings.ReplaceAll(getSignupMySQL, prefixMarker, prefix),
		getSignupByContactDigest:        strings.ReplaceAll(getSignupByContactDigestMySQL, prefixMarker, prefix),
		getSignupCreatedAt:              strings.ReplaceAll(getSignupCreatedAtMySQL, prefixMarker, prefix),
		insertSignup:                    strings.ReplaceAll(insertSignupMySQL, prefixMarker, prefix),
		listLists:                       strings.ReplaceAll(listListsMySQL, prefixMarker, prefix),
		listListsDescending:             strings.ReplaceAll(listListsDescendingMySQL, prefixMarker, prefix),
		listOpenLists:                   strings.ReplaceAll(listOpenListsMySQL, prefixMarker, prefix),
		listOpenListsDescending:         strings.ReplaceAll(listOpenListsDescendingMySQL, prefixMarker, prefix),
		listSignups:                     strings.ReplaceAll(listSignupsMySQL, prefixMarker, prefix),
		listSignupsDescending:           strings.ReplaceAll(listSignupsDescendingMySQL, prefixMarker, prefix),
		listSignupsForSubject:           strings.ReplaceAll(listSignupsForSubjectMySQL, prefixMarker, prefix),
		listSignupsForSubjectDescending: strings.ReplaceAll(listSignupsForSubjectDescendingMySQL, prefixMarker, prefix),
		transitionSignup:                strings.ReplaceAll(transitionSignupMySQL, prefixMarker, prefix),
		updateList:                      strings.ReplaceAll(updateListMySQL, prefixMarker, prefix),
		updateSignupNotes:               strings.ReplaceAll(updateSignupNotesMySQL, prefixMarker, prefix),
		withdrawSignup:                  strings.ReplaceAll(withdrawSignupMySQL, prefixMarker, prefix),
		withdrawSignupsForSubject:       strings.ReplaceAll(withdrawSignupsForSubjectMySQL, prefixMarker, prefix),
	}
}

